// ## 1. Identity & Authentication Boundary
// Assets: user identity, session token, signing key (secret)
// Boundary: internet (untrusted) -> Resource API (trusted)
// INVARIANT: a request is accepted as user U only if it carries a token
//   that is (a) signature-valid, (b) unexpired, (c) not revoked in the store.
// Abuse case: attacker replays a logged-out user's token -> MUST be rejected.

import { verify } from './jwt'
import { isRevoked } from './sessions'
import { audit } from './audit'

export async function authenticate(req: Request): Promise<Principal> {
  const token = bearer(req)                       // no token => no identity
  if (!token) throw new AuthError('missing token')

  const claims = verify(token, SIGNING_KEY)       // (a) signature or throw
  if (claims.exp < now()) throw new AuthError('expired')      // (b) expiry
  if (await isRevoked(claims.sid)) throw new AuthError('revoked') // (c) revocation

  await audit('auth.accept', { sub: claims.sub, sid: claims.sid })
  return { id: claims.sub, sid: claims.sid }      // least-privilege principal
}

session-token-security.code:
import jwt from 'jsonwebtoken'
import { randomUUID } from 'crypto'

const SECRET = process.env.SESSION_SIGNING_SECRET // 32+ bytes, server-only, NEVER in repo
if (!SECRET) throw new Error('SESSION_SIGNING_SECRET not configured')

// Mint: short-lived, uniquely identified so it can be revoked.
export function issueSession(userId: string, sessionId: string) {
  const jti = randomUUID()
  const token = jwt.sign({ sub: userId, sid: sessionId, jti }, SECRET, {
    algorithm: 'HS256',
    expiresIn: '15m', // short expiry caps the replay window
  })
  return { token, jti }
}

export function sessionCookie(token: string) {
  // HttpOnly: JS cannot read it (blocks XSS theft)
  // Secure: HTTPS only (blocks network sniffing)
  // SameSite=Strict: not sent cross-site (blocks CSRF replay)
  return `session=${token}; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=900`
}

// Verify on EVERY request: signature + expiry (jwt.verify) AND revocation.
export async function authenticate(token: string, revoked: RevocationStore) {
  const claims = jwt.verify(token, SECRET, { algorithms: ['HS256'] }) as any
  if (await revoked.has(claims.jti)) {
    throw new Error('token revoked') // logout / breach kill-switch
  }
  return { userId: claims.sub, sessionId: claims.sid }
}

authorization-rbac-abac.code:
// threat_model_and_access_control_packet.md → §Access Control (enforced)
// Asset: Invoice (financial). Boundary: tenant isolation. Threat: BOLA (API#1).
export function authorizeInvoiceRead(subject: Subject, invoice: Invoice): Decision {
  // 1. RBAC — coarse capability. Deny-by-default: no role, no read.
  if (!subject.roles.includes('billing_reader')) {
    audit.log({ event: 'authz.deny', reason: 'rbac.no_role', sub: subject.id })
    return { allow: false, status: 403 }
  }
  // 2. ABAC — the row-level predicate RBAC cannot express.
  //    Least privilege: a reader may read only invoices in their own tenant.
  if (subject.tenantId !== invoice.tenantId) {
    audit.log({ event: 'authz.deny', reason: 'abac.cross_tenant',
                sub: subject.id, subTenant: subject.tenantId,
                objTenant: invoice.tenantId, objId: invoice.id })
    return { allow: false, status: 403 }   // <-- stops User A → tenant 88
  }
  audit.log({ event: 'authz.allow', sub: subject.id, objId: invoice.id })
  return { allow: true, status: 200 }
}

object-level-authorization.code:
export async function getInvoice(req: Request, res: Response) {
  const callerId = req.auth.userId            // from verified token, NEVER from body/query
  const invoiceId = req.params.id

  // Object-level authorization: scope the read to the caller's own rows.
  const invoice = await db.invoice.findFirst({
    where: { id: invoiceId, ownerId: callerId },
  })

  if (!invoice) {
    audit.log({ actor: callerId, object: `invoice:${invoiceId}`, action: 'read', result: 'deny' })
    return res.status(404).json({ error: 'Not found' })   // 404, not 403 — no existence leak
  }

  audit.log({ actor: callerId, object: `invoice:${invoiceId}`, action: 'read', result: 'allow' })
  return res.status(200).json(invoice)
}

