// ── VULNERABLE ──────────────────────────────────────────
export async function getOrder(req: Request) {
  const id = req.query.id as string          // trusted blindly
  const sql = `SELECT * FROM orders WHERE id = ${id}`  // sink: string-built SQL
  return db.query(sql)                        // id=0 OR 1=1-- dumps every row
}

// ── GOLD: validate at boundary, parameterize at sink ────
import { z } from 'zod'
const OrderQuery = z.object({ id: z.coerce.number().int().positive() })

export async function getOrder(req: Request, session: Session) {
  const { id } = OrderQuery.parse(req.query)   // allow-list: int > 0, else throw
  const rows = await db.query(                  // value bound as DATA, not code
    'SELECT * FROM orders WHERE id = $1 AND owner_id = $2',
    [id, session.userId],                       // least privilege: own rows only
  )
  audit.log('order.read', { id, actor: session.userId, allowed: rows.length > 0 })
  return rows
}

secure-api-design.code:
export async function getOrder(req: Request, session: Session) {
  const orderId = req.params.id                 // UNTRUSTED: client controls this
  const callerId = session.userId               // TRUSTED: derived from the verified token

  // Least privilege: scope the read to the caller. A non-owner matches zero rows.
  const order = await db.order.findFirst({
    where: { id: orderId, userId: callerId },
  })

  if (!order) {
    audit.log('order.read.denied', { callerId, orderId, ip: req.ip })
    return json({ error: 'Not found' }, { status: 404 })
  }

  audit.log('order.read.allowed', { callerId, orderId })
  return json(order)
}

