# WEAK — passes AuthN, fetches by id, never checks ownership (IDOR)
@requires_login
def get_invoice(request, invoice_id):
    invoice = db.invoices.get(id=invoice_id)   # trusts the id
    return json(invoice)                        # 200 for ANY logged-in caller

# ABUSE CASE (curl): attacker owns 1001, requests 1002
#   curl -H "Cookie: sid=<attacker>" /invoices/1002  ->  200  (LEAK)

# GOLD — object-level authorization at the data boundary
@requires_login
def get_invoice(request, invoice_id):
    invoice = db.invoices.get(id=invoice_id)
    if invoice is None or invoice.owner_id != request.user.id:
        audit.log("authz_denied", user=request.user.id, obj=invoice_id)
        raise Forbidden(403)                    # do NOT leak 404-vs-403 existence
    return json(invoice)

#   curl -H "Cookie: sid=<attacker>" /invoices/1002  ->  403  (DENIED + logged)

incident-response.code:
// PROOF: abuse case -> denied request -> audit-log evidence -> retest
// Asset: DELETE /accounts/:id  |  Boundary: gateway->accounts svc
// Control: RBAC least-privilege (support may READ, never DELETE)

const POLICY = {
  support: ['account:read'],
  admin: ['account:read', 'account:delete'],
} as const

function authorize(role: keyof typeof POLICY, action: string) {
  const allowed = POLICY[role].includes(action)
  auditLog.append({                 // observed denial: evidence, not a vibe
    ts: Date.now(),
    actor: role,
    action,
    decision: allowed ? 'ALLOW' : 'DENY',
    reason: allowed ? 'policy-grant' : 'least-privilege-violation',
  })
  if (!allowed) throw new ForbiddenError(action) // 403
}

// Abuse case: support token attempts the privileged delete
test('support token is DENIED account:delete and it is logged', () => {
  expect(() => authorize('support', 'account:delete')).toThrow(ForbiddenError)
  const line = auditLog.last()
  expect(line.decision).toBe('DENY')            // audit-log evidence
  expect(line.reason).toBe('least-privilege-violation')
})

// Repair retest: admin still works (control is least-privilege, not a wall)
test('admin token is ALLOWED account:delete', () => {
  expect(() => authorize('admin', 'account:delete')).not.toThrow()
})
